CREATE TABLE IF NOT EXISTS nigeria_legal_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_code text NOT NULL UNIQUE, title text NOT NULL, instrument_type text NOT NULL, issuing_body text NOT NULL, source_url text NOT NULL, publication_or_commencement_date date, authority_level text NOT NULL DEFAULT 'Official', reliability_score numeric(5,2) NOT NULL DEFAULT 0, verification_status text NOT NULL DEFAULT 'Verified', scope text NOT NULL DEFAULT 'Nigeria', retrieved_at timestamptz NOT NULL DEFAULT now(), review_due date, notes text);
CREATE TABLE IF NOT EXISTS nigeria_legal_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_id uuid NOT NULL REFERENCES nigeria_legal_sources(id) ON DELETE CASCADE, rule_code text NOT NULL UNIQUE, domain_code text NOT NULL, title text NOT NULL, statement text NOT NULL, legal_force text NOT NULL, mandatory boolean NOT NULL DEFAULT true, applicability text NOT NULL, confidence_score numeric(5,2) NOT NULL DEFAULT 0, effective_from date, effective_to date, review_due date, evidence_required text, competent_authority text, indigenous_or_community_relevance text, investment_relevance text, status text NOT NULL DEFAULT 'Active');
CREATE TABLE IF NOT EXISTS nigeria_rights_domains (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), domain_code text NOT NULL UNIQUE, domain_name text NOT NULL, institutional_position text NOT NULL, primary_authority text, source_rule_codes text[], status text NOT NULL DEFAULT 'Active');
CREATE TABLE IF NOT EXISTS nigeria_rule_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), rule_id uuid NOT NULL REFERENCES nigeria_legal_rules(id) ON DELETE CASCADE, review_type text NOT NULL, review_due date, reviewer_reference text, outcome text, notes text, reviewed_at timestamptz, status text NOT NULL DEFAULT 'Pending');
CREATE INDEX IF NOT EXISTS idx_ng_rules_domain ON nigeria_legal_rules(domain_code,status);
CREATE INDEX IF NOT EXISTS idx_ng_rules_source ON nigeria_legal_rules(source_id);
CREATE INDEX IF NOT EXISTS idx_ng_reviews_due ON nigeria_rule_reviews(review_due,status);